CREATE TABLE wompi_events (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, event_type VARCHAR(60) NOT NULL, environment VARCHAR(4) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, transaction_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL, reference VARCHAR(120) NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NULL, amount_in_cents BIGINT NULL, payment_method VARCHAR(40) NULL, payload JSON NOT NULL, received_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), processed_at DATETIME(6) NULL, PRIMARY KEY (id), UNIQUE KEY wompi_events_once (user_id,transaction_id,status), KEY wompi_events_reference (user_id,reference), KEY wompi_events_recent (user_id,received_at), CONSTRAINT wompi_events_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
